ALTER TABLE "race_entrants" DROP CONSTRAINT "race_entrants_identity_kind";--> statement-breakpoint
ALTER TABLE "race_entrants" ADD CONSTRAINT "race_entrants_identity_kind" CHECK (("race_entrants"."kind" = 'human' and "race_entrants"."account_id" is not null and "race_entrants"."bot_level" is null) or ("race_entrants"."kind" = 'guest' and "race_entrants"."account_id" is null and "race_entrants"."member_id" is null and "race_entrants"."bot_level" is null and "race_entrants"."display_name_snapshot" = '#' || "race_entrants"."ordinal"::text) or ("race_entrants"."kind" = 'bot' and "race_entrants"."account_id" is null and "race_entrants"."member_id" is null and "race_entrants"."bot_level" is not null and "race_entrants"."bot_level" in ('noob', 'beginner', 'intermediate', 'expert', 'impossible')));